import 'dart:io';
import 'dart:convert';

void main() {
  final dir = Directory('test/fixtures');
  if (!dir.existsSync()) {
    dir.createSync(recursive: true);
  }

  // Base64 of a 50x100 green JPEG with EXIF Orientation = 6 (Rotate 90 CW)
  // This effectively means the display size is 100x50 landscape
  const exifRotatedBase64 = 
    "";

  File('test/fixtures/rotated_exif.jpg').writeAsBytesSync(base64Decode(exifRotatedBase64));

  print("Fixtures generated in test/fixtures/");
}
